-- Cadastro oficial de postos da ANP (dados abertos: dados cadastrais dos revendedores varejistas + API Revendedores)
-- para as cidades do app, as da rota Maringá–Guaíra e Alto Piquiri. Coordenadas: API da ANP, conferidas contra o
-- limite do município (IBGE); algumas do OpenStreetMap (© colaboradores do OpenStreetMap, ODbL). Gerado automaticamente.
create or replace function mp_nome_cidade(mun text) returns text language sql immutable as $$
  select case upper(coalesce(mun, ''))
    when 'MARECHAL CANDIDO RONDON' then 'Marechal Cândido Rondon'
    when 'FOZ DO IGUACU' then 'Foz do Iguaçu'
    when 'CAMPO MOURAO' then 'Campo Mourão'
    when 'PARANAVAI' then 'Paranavaí'
    when 'FRANCISCO BELTRAO' then 'Francisco Beltrão'
    when 'MARINGA' then 'Maringá'
    when 'PAICANDU' then 'Paiçandu'
    when 'IPORA' then 'Iporã'
    when 'GUAIRA' then 'Guaíra'
    else replace(replace(replace(replace(initcap(lower(mun)), ' Do ', ' do '), ' Da ', ' da '), ' De ', ' de '), ' Dos ', ' dos ') end;
$$;

on conflict (cnpj) do update set lat = coalesce(excluded.lat, anp_revendas.lat), lng = coalesce(excluded.lng, anp_revendas.lng),
  coord_fonte = coalesce(excluded.coord_fonte, anp_revendas.coord_fonte), atualizado_em = now();
select anp_ligar_coordenadas();
